    case metadataNotFound(path: String)
    case metadataInvalid(message: String)
    case loadError(message: String)
    case inferenceError(message: String)
    case abortedForCloudFallback(reason: String)
    case streamingNotSupported
    case notLoaded
    case configError(message: String)
    case networkError(message: String)
    case offline(message: String)
    case ioError(message: String)
    case cacheError(message: String)
    case pipelineError(message: String)
    case circuitOpen(message: String)
    case rateLimited(retryAfterSecs: UInt64)
    case timeout(timeoutMs: UInt64)
    case missingArtifact(message: String)
    case unsupportedModelCapability(message: String)
    case unsupportedBackendCapability(message: String)
    case invalidImage(message: String)
    /// The host called `cancel` — today, on a model download.
    case cancelled(message: String)
    /// Telemetry delivery is incomplete or unknown; do not rerun inference.
    case telemetryDelivery(message: String)

    @inlinable static func decode(from reader: inout WireReader) -> XybridError {
        let tag = reader.readU32()
        switch tag {
        case 0:
            return .modelNotFound(id: reader.readString())
        case 1:
            return .directoryNotFound(path: reader.readString())
        case 2:
            return .metadataNotFound(path: reader.readString())
        case 3:
            return .metadataInvalid(message: reader.readString())
        case 4:
            return .loadError(message: reader.readString())
        case 5:
            return .inferenceError(message: reader.readString())
        case 6:
            return .abortedForCloudFallback(reason: reader.readString())
        case 7:
            return .streamingNotSupported
        case 8:
            return .notLoaded
        case 9:
            return .configError(message: reader.readString())
        case 10:
            return .networkError(message: reader.readString())
        case 11:
            return .offline(message: reader.readString())
        case 12:
            return .ioError(message: reader.readString())
        case 13:
            return .cacheError(message: reader.readString())
        case 14:
            return .pipelineError(message: reader.readString())
        case 15:
            return .circuitOpen(message: reader.readString())
        case 16:
            return .rateLimited(retryAfterSecs: reader.readU64())
        case 17:
            return .timeout(timeoutMs: reader.readU64())
        case 18:
            return .missingArtifact(message: reader.readString())
        case 19:
            return .unsupportedModelCapability(message: reader.readString())
        case 20:
            return .unsupportedBackendCapability(message: reader.readString())
        case 21:
            return .invalidImage(message: reader.readString())
        case 22:
            return .cancelled(message: reader.readString())
        case 23:
            return .telemetryDelivery(message: reader.readString())
